  m1052: "Default: 10",
  m1053:
    "If this interval passes since the last planning round or task start without another trigger, a planning round starts automatically to recover stalls and supervise running Workers. Minimum: 10 minutes.",
  m1054: "Dispatch first intent directly (description + objectives)",
  m1055:
    "On creation, dispatch the description and objectives as one intent so a Worker starts without waiting for initial planning. The planner evaluates and supplements the result afterward. Recommended for CTF-like scenarios often solved by one Worker. When disabled, planning precedes execution.",
