  m2567:
    "Worker outputs: i9→fa7 live DC01/FS01/JENKINS; i11→fa8 unauthenticated Groovy and fa9 plaintext acme\\\\svc_deploy credentials; i12→fa10 svc_sql TGS cracked as Sql@2020. svc_deploy is Domain Admins; i13 used it for psexec and secretsdump on DC01. g4 appears met; verify the finding evidence chain first.",
  m2568: "list_findings — verify confirmed evidence of DC01 compromise",
