  m1037: "关联任务",
  m1038: "最多关联",
  m1039: "个任务。以只读方式实时继承它们的持久化黑板、资产范围和相关流量。新任务写入自己的黑板。",
  m1040: "关联公司资产范围",
  m1041:
    "创建时，所选公司的现有资产会被添加为测试资产。域名、IP、CIDR、ICP 和公司关键词将为 Agent 提供范围上下文。这不会自动创建意图，也不会覆盖执行目标。",
  m1042: "任务资产黑名单／白名单规则（可选）",
  m1043:
    "仅适用于该任务，不作为全局规则。黑名单规则（含全局规则）优先检查；任意命中即禁止测试。若无黑名单命中且存在任务白名单规则，则必须有一条白名单规则命中。未设置白名单规则时，不启用白名单。",
  m1044: "LLM 配置链",
  m1045: "故障转移按列表顺序进行。首个配置为当前配置；只有明确返回配额不足时才会切换到下一个。",
  m1046: "高级设置",
  m1047: "超时 · 心跳 · 首个意图",
  m1048: "任务超时（分钟，可选）",
  m1049: "留空 = 不限制",
  m1050: "到达期限后开始优雅收尾：各 Agent 回写结果，规划器做出最终评估。任务以超时状态结束。",
  m1051: "规划器心跳（分钟）",
  m1052: "默认：10",
  m1053:
    "若自上一轮规划或任务开始后经过该间隔仍无其他触发，则自动启动一轮规划，以从停滞中恢复并监督运行中的 Worker。最小值：10 分钟。",
  m1054: "直接派发首个意图（描述 + 目标）",
  m1055:
    "创建时将描述和目标作为一个意图派发，使 Worker 无需等待初始规划即可开始。规划器随后会评估并补充其结果。推荐用于通常由单个 Worker 解决的 CTF 类场景。关闭时，先规划后执行。",
  m1056: "资产覆盖功能",
  m1057:
    "默认启用：计算并展示测试覆盖率、在图谱上显示进度，并自动累积测试范围。关闭后将隐藏覆盖率和图谱进度，且 Agent 不会获得范围相关工具。已关联的公司资产范围不受影响。",
