  m1274: "仅启用了拦截的工具会进行规则检查，其他工具直接放行",
  m1275: "连接重试",
  m1276: "SDK · HTTP 200 之前",
  m1277:
    "连接失败或尚未收到 HTTP 200：连接重置、读写超时、DNS 解析失败、其他网络错误，以及 HTTP 408、429、500、502、503、504。",
  m1278: "其他状态码（400 / 401 / 403 / 404 / 413 / 422 等）属于确定性拒绝，重试仍会失败，因此会立即向上抛出。",
  m1279: "原样重新发送同一请求。一旦流式传输开始（已收到 HTTP 200），中断将由其他层处理。",
  m1280: "重试次数",
  m1281: "指数退避 0.5s → 1s → 2s（最长 8s）",
  m1282: "-1 = 不重试，失败立即向上抛出",
  m1283: "空响应重试",
  m1284: "SDK · 仅限 OpenAI 格式",
  m1285: "HTTP 200 且 finish_reason 为正常停止，但完全没有内容块。网关空帧、缺失推理字段或采样异常都可能导致此情况。",
  m1286: "不包括因 max_tokens 截断导致的空内容。此时应提高输出上限，重新发送仍会触及同一上限。",
  m1287: "会重新发送整个提示词，长上下文下开销很大，建议保持较小的次数。",
  m1288: "-1 = 空响应原样返回",
  m1289: "同提供商安全窗口重试",
  m1290: "应用层 · 输出交付之前",
  m1291:
    "流式连接建立（HTTP 200）之后、尚未向调用方交付任何 token 之前发生的失败，例如连接断开、提供商过载或流内 429/5xx 错误。",
  m1292:
    "以下情况不重试：配额耗尽（402 / insufficient_quota，由配置轮换处理）、上下文过长（413 / 上下文长度，由压缩处理），以及确定性的 400 / 401 / 403 / 404 / 422 拒绝。",
  m1293: "在同一配置上重放同一请求。由于尚未交付任何输出，重放不会造成模型输出或工具执行的重复。",
  m1294: "指数退避 0.5s → 1s（最长 4s）",
  m1295: "-1 = 将流式失败交给外层意图重跑层处理",
  m1296: "轮换熔断器",
  m1297: "应用层 · 全局唯一的进程级状态",
  m1298:
    "瞬时失败（429、5xx、网络错误）在连续失败次数达到阈值后触发熔断。确定性失败，如余额不足（402）、密钥无效（401/403）或模型不存在（404），会立即触发熔断。",
  m1299: "只要成功一次即重置计数，因此间歇性失败不会逐渐累积至熔断。",
  m1300: "已熔断的配置进入冷却期，轮换时将被跳过。该状态在重启后仍会保留。",
  m1301: "触发熔断的连续失败次数",
  m1302: "阶梯：1 分钟 → 5 分钟 → 30 分钟",
  m1303: "-1 = 瞬时失败永不熔断（确定性失败仍会熔断）",
  m1304: "意图重跑",
  m1305:
    "当前面各层都无法恢复时，执行器会以 model_error 结束：内层重试已耗尽，或已开始交付输出后流式传输失败、无法安全重放，必须从头重启整个意图。",
  m1306: "配额耗尽由配置轮换处理，不在此处重跑。已暂停、已终止或正在收尾的任务会立即退出，不会等待退避结束。",
  m1307: "从头重新执行整个意图。这是最外层，因此每次重跑都会使所有内层的尝试次数成倍增加。",
  m1308: "重跑次数",
  m1309: "固定 3s",
  m1310: "-1 = 不重跑，立即将意图标记为受阻",
  m1311: "触发条件",
  m1312: "此处不处理",
  m1313: "默认 {p0}",
  m1314: "间隔（ms）",
  m1315: "默认退避",
  m1316: "固定 {p0}",
  m1317: "留空 = 默认； ",
  m1318: "重试覆盖",
  m1319:
    "仅针对此配置覆盖全局的重试与退避默认值。留空的字段沿用全局设置；-1 表示禁用该重试层。设置间隔后将以固定延迟取代指数退避。熔断器和意图重跑为进程级设置，只能全局修改。",
  m1320: "读取重试策略失败：{p0}",
  m1321: "已保存并立即生效（当前调用仍使用旧设置）",
  m1322: "正在加载重试策略…",
  m1323: "模型调用失败后，会由内向外依次经过五个重试层：",
  m1324: "连接 → 空响应 → 同提供商安全窗口 → 轮换熔断器 → 意图重跑",
  m1325: "。外层仅在内层耗尽后才会执行，因此次数会",
  m1326: "成倍叠加",
  m1327:
    "。若每一层都设得很高，一次中断就可能耗费数十次请求。所有字段留空即保持当前默认值和现有行为。前三层可按模型配置单独覆盖。",
  m1328: "全部恢复默认",
  m1329: "不发送（默认）",
  m1330: "max_tokens（默认）",
  m1331:
    "选择发送哪个输出上限字段。max_tokens 为默认值，大多数兼容网关均可识别。OpenAI 官方推理模型（o 系列 / GPT-5）要求使用 max_completion_tokens，若发送 max_tokens 会以 unsupported_parameter 拒绝。",
  m1332: "仅 OpenAI 格式可选。Anthropic 始终使用 max_tokens。",
  m1333: "仅 OpenAI 格式可选。Responses API 始终使用 max_output_tokens。",
  m1334: "未配置密钥",
  m1335: "缺少 API 密钥，无法调用",
