  m1355:
    "默认关闭：绑定了配置的 Agent 或任务只使用该配置，失败时不会悄悄切换模型。启用后，指定配置失败时将转入下方的轮换链。",
  m1356: "绑定配置失败转移开关",
  m1357: "轮换顺序",
