  m1368: "暂无配置",
  m1369:
    "当前配置始终排在首位，其余按各配置设定的优先级从高到低排列。失败的配置会进入冷却（60s → 5min → 30min）并被跳过，之后自动重新加入。上下文窗口不足的配置会被跳过。指定了模型的 Agent 和任务默认不参与轮换。",
