  m1390: "从 API 加载可用模型",
  m1391: "Base URL（可选）",
  m1392: "代理（可选）",
  m1393:
    "仅 LLM 出站请求使用此代理。支持 HTTP/HTTPS/SOCKS5 及认证信息（如 socks5://user:pass@host:port；密码中的特殊字符需进行 URL 编码）。留空表示直连。",
  m1394: "自定义会话请求头（可选）",
  m1395: "例如 x-session-id（留空 = 不发送）",
  m1396: "设置请求头名称后，每个请求都会携带该 HTTP 请求头，其值自动设为",
  m1397: "当前会话 ID",
  m1398:
    "（聊天会话如 conv-12，执行器如 exp3-worker-i87）。适用于利用会话请求头实现提示词缓存或粘性路由的网关。同一会话内各轮保持不变，不同会话之间互不相同。留空则禁用。",
  m1399: "已设置（{p0}）；留空则保持不变",
  m1400: "每秒速率限制",
  m1401: "每分钟速率限制",
  m1402: "上下文窗口（K）",
  m1403:
    "速率限制为 0 表示不限制，由所有 Agent 共享。上下文窗口单位为 K（千 token）：0 默认为 200K；最大 1000（1M）。设置过大会导致压缩无法触发。",
  m1404: "轮换优先级",
  m1405: "数值越大越优先选用。无论此值如何，当前配置始终排在首位。优先级相同的配置轮流居首，以分摊配额用量。",
  m1406: "启用后，此配置不参与故障转移，但仍可被 Agent 或任务显式选用。适用于为特定 Agent 保留的高成本配置。",
  m1407: "流式输出",
  m1408:
    "默认启用：SSE 流式传输可实时显示进度和 token 计数。禁用后：stream:false 一次性返回完整响应，可规避网关 SSE 实现缺陷（如空帧或推理字段丢失），但无法实时显示进度。",
  m1409: "流式输出",
  m1410: "输出上限 · 最大 token 数",
  m1411:
    "每次回复最多生成的 token 数，随每个请求发送。0（默认）表示不发送该字段，使用服务端默认值。这与上下文窗口不同，后者是模型的总容量，仅在本地用于计算压缩阈值。上限过小可能导致推理尚未产出答案就被截断。",
  m1412: "上限字段名",
  m1413: "思考开关 · thinking.type",
  m1414:
    "控制是否发送 thinking 字段。“省略”不发送该字段，适用于不支持它的模型（如 MiniMax）；“关闭”发送 disabled；“开启”发送 enabled。与下方的推理强度设置相互独立。",
  m1415: "推理强度 · reasoning_effort",
  m1416:
    "独立的推理强度级别（OpenAI reasoning_effort / Anthropic output_config.effort）。部分 API 仅凭推理强度即可启用推理，无需 thinking 字段，因此推理强度可单独设置。",
