  m1656: "查看数据包和额外的工具调用会增加 token 用量。",
  m1657:
    "TCP 流量、未抓取或未匹配的流量仍可上报。此设置不影响抓包、手动绑定或查看已保存的证据。对 Agent 的下一轮生效；关闭后会立即拒绝新的自动绑定。",
