  m2412: "解析侧边提问数据失败。请重新打开面板",
  m2413: "未授权",
  m2414:
    "# ScopeWeaver 渗透测试报告 — Acme Corp\n\n## 概览\n- 范围：acme.com（含 www / admin / api / shop / vpn 子域名）\n- 已确认漏洞：6（高危 3 · 中危 3 · 低危 2）\n- 引擎模式：探索中\n\n## 关键漏洞\n1. **[高危] 默认管理员密码** admin.acme.com admin/admin123 → 获得完整管理员权限。\n2. **[高危] SQL 注入** www.acme.com/search?q= → 可读取 acme_prod。\n3. **[高危] IDOR** api.acme.com/v1/orders?id= → 可泄露其他用户的订单，包括电话和地址。\n4. **[中危] 反射型 XSS**、**暴露的 .git 源码**、**登录无速率限制**。\n\n## 建议\n- 强制修改管理员密码并启用 MFA；禁止使用默认凭据。\n- 使用参数化的搜索查询和输出编码。\n- 强制实施对象级 API 鉴权并替换弱 JWT 密钥。\n\n> 本演示报告由模拟数据生成，仅用于界面演示。",
