  m2643: "导出了两个域服务账户的明文口令。",
  m2644: "未认证的 Jenkins RCE 已确认；导出了两个域服务凭据。",
  m2645: "使用 svc_deploy 认证，然后通过 GetUserSPNs 请求服务账户的 TGS 票据以进行 Kerberoasting。",
  m2646: "获取了 svc_sql 的 TGS 票据（Kerberos RC4）。",
