  m2648: "Kerberoasting 恢复了 svc_sql 口令；已记录到图谱，用于域控制器评估。",
  m2649: "svc_deploy 来自 Jenkins 凭据。检查其组成员身份；Domain Admins 成员身份允许直接对 DC01 执行 psexec。",
  m2650: "svc_deploy 是 Domain Admins 成员。",
  m2651: "以 SYSTEM 身份登录 DC01。",
  m2652: "导出了域 NTLM 哈希，包括 krbtgt；可实现黄金票据持久化。",
  m2653: "DC01 已控制；用 secretsdump 导出了域哈希。目标达成。",
