    "www-data 权限有限；先排查本地提权（sudo -l 看起来有戏）。拿到 root 后，利用 DMZ 跳板进行内网发现，优先关注域控制器与 Jenkins。",
  m2660: "内网扫描完成。Jenkins 允许未认证访问吗？",
