  m2710: "[模型] 删除目标生产文件（D4）",
  m2711: "[模型] 可能是备份表；是否为生产数据尚不明确",
  m2712: "# 复核摘要\n\n本轮验证已完成。整理现有证据与后续建议。",
  m2713: "[模型] 将现有结论写入本地报告，不改动业务数据。",
  m2714: "总结已完成的检查，并将结论与证据引用写入 reports/summary.md。\n保留未验证项，且不改动业务数据。",
  m2715: "将本轮现有证据汇总为一份复核摘要。",
  m2716: "已读取 3 条证据引用。\n记录包含请求时间、结果摘要和本地文件位置。",
  m2717: "已成功写入 reports/summary.md\n写入 68 个字符。",
  m2718: "核实备份表的用途；删除前务必确认。",
  m2719: "[模型] 可能是备份表；无法确认是否包含生产数据。",
  m2720: "Acme 管理后台入口讨论",
  m2721: "API 鉴权面复核",
  m2722: "内网横向移动 · DMZ 到域控制器的路径规划",
  m2723: "管理后台在哪里，我们从哪开始？",
  m2724: "检查 admin.acme.com 的登录技术栈与防护（验证码/速率限制），然后选择默认凭据或字典。",
  m2725: "Element-UI 管理后台，有 CSRF 令牌但无验证码。",
  m2726: "连续五次尝试均未触发锁定/验证码，说明无速率限制；可进行暴力破解。",
  m2727:
    "结论：Element-UI 管理后台无验证码或速率限制。先尝试默认凭据（admin/admin、admin/admin123、admin/123456），必要时再用 top1000。已向执行器分配一个高优先级的默认凭据意图。",
  m2728: "成功了吗？",
  m2729: "成功了。admin/admin123 打开了控制台。已记录为高危漏洞及管理员访问的证明。下一步是敏感用户数据（目标 2）。",
  m2730: "复核 api.acme.com 的鉴权风险。",
  m2731: "检查 API 认证与关键端点行为，然后评估 IDOR/JWT 风险。",
  m2732: "标准用户令牌可用。",
  m2733: "echo '<jwt>' | cut -d. -f1 | base64 -d; # 检查算法",
  m2734: "HS256 对称签名；弱密钥可被离线破解并伪造。",
  m2735:
    "两条路径：/v1/orders?id= 的连续 ID 提示存在 IDOR；尝试换一个 ID。HS256 JWT 可能允许弱密钥破解并伪造任意 sub。两者都已有意图。先从 IDOR 入手，因为它成本低且直接。",
  m2736: "我们已拿到 shell。接下来如何评估内网？",
  m2737: "www-data 权限不足以进行横向移动。先排查本地提权，拿到 root 后再利用 DMZ 跳板进行发现。",
  m2738: "先提权：sudo -l 显示 python3 免密。然后通过 DMZ 跳板用 fscan 发现内网主机，重点关注域控制器和 CI/CD 服务器。",
  m2739: "发现三台内网主机；Jenkins 的 8080 端口开放。有用吗？",
  m2740: "/script 无需认证即可直接访问。",
  m2741: "是的，未认证的 Script Console 允许 Groovy RCE。有提示优先处理这台主机。进入后，检查凭据库中的域账户。",
  m2742: "已获取域凭据；svc_deploy 属于 Domain Admins。直接打 DC01 吗？",
  m2743:
    "是的。具备 Domain Admins 的 svc_deploy 可用 psexec 访问 DC01，随后用 secretsdump 获取域哈希。secretsdump 会触发拦截规则；本次演示中已提前批准。",
  m2744: "目标已达成。总结攻击链。",
  m2745:
    "完整攻击链：\n1. .git 泄露 → 源码审查与硬编码凭据\n2. Shop Fastjson RCE → DMZ 反弹 shell\n3. Sudo 提权 → root 立足点\n4. 内网发现 → DC01/FS01/Jenkins\n5. 未认证的 Jenkins → svc_deploy 域凭据\n6. Kerberoasting → svc_sql 口令\n7. svc_deploy 属于 Domain Admins → psexec DC01 → secretsdump 域哈希\n\n四个目标全部达成；17 个漏洞（7 高危 / 4 中危 / 2 低危 + 8 个内网链条项）。",
